window.SL_SEARCH = [{"a":"Does a pendulum's period change as its swing gets smaller? This method times a pendulum at a large and at a small swing, compares the two periods, and revises the starting hypothesis.","k":"Overview","t":"Pendulum period","u":"index.html","x":""},{"a":"Set up a pendulum of fixed length and a hand stopwatch, and decide to time ten full swings in each trial.","k":"Stage","t":"Prepare","u":"stages/prepare.html","x":"start stage Prepare by assistant from state [\n  set information to [set swing-count to 10]\n  set environment to [\n    set pendulum to [set length to 1 set unit to \"m\"]\n    set timer to \"hand stopwatch\"\n  ]\n  set factors to [set reaction-time to unknown]\n]\n  about \"Set up a pendulum of fixed length and a hand stopwatch, and decide to\n  time ten full swings in each trial.\"\nend stage with state [\n  set information to [set swing-count to 10]\n  set environment to [\n    set pendulum to [set length to 1 set unit to \"m\"]\n    set timer to \"hand stopwatch\"\n  ]\n  set factors to [set reaction-time to unknown]\n]"},{"a":"Time ten full swings at a large and at a small swing, and derive the period of each.","k":"Stage","t":"Observe","u":"stages/observe.html","x":"start stage Observe by assistant from state [\n  set information to [\n    set large-swing to [\n      set elapsed to 20.1 with uncertainty [\n        set declared to [set reaction-time to [set type to \"epistemic\" set estimate to 0.2 set unit to \"s\"]]\n      ]\n      set swing-count to 10\n      set unit to \"s\"\n    ]\n    set small-swing to [\n      set elapsed to 20.0 with uncertainty [\n        set declared to [set reaction-time to [set type to \"epistemic\" set estimate to 0.2 set unit to \"s\"]]\n      ]\n      set swing-count to 10\n      set unit to \"s\"\n    ]\n  ]\n  set environment to [\n    set pendulum to [set length to 1 set unit to \"m\"]\n    set timer to \"hand stopwatch\"\n  ]\n  set factors to [set reaction-time to unknown]\n]\n  about \"Time ten full swings at a large and at a small swing, and derive the\n  period of each.\"\n  do calculate-period with [\n    elapsed at elapsed of information.large-swing\n    swings at swing-count of information.large-swing\n  ] into period of information.large-swing\n  do calculate-period with [\n    elapsed at elapsed of information.small-swing\n    swings at swing-count of information.small-swing\n  ] into period of information.small-swing\nend stage with state [\n  set information to [\n    set large-swing to [\n      set elapsed to 20.1 with uncertainty [\n        set declared to [set reaction-time to [set type to \"epistemic\" set estimate to 0.2 set unit to \"s\"]]\n      ]\n      set swing-count to 10\n      set unit to \"s\"\n      set period to unknown\n    ]\n    set small-swing to [\n      set elapsed to 20.0 with uncertainty [\n        set declared to [set reaction-time to [set type to \"epistemic\" set estimate to 0.2 set unit to \"s\"]]\n      ]\n      set swing-count to 10\n      set unit to \"s\"\n      set period to unknown\n    ]\n  ]\n  set environment to [\n    set pendulum to [set length to 1 set unit to \"m\"]\n    set timer to \"hand stopwatch\"\n  ]\n  set factors to [set reaction-time to unknown]\n]"},{"a":"Divide the elapsed time by the number of full swings.","k":"Procedure","t":"calculate-period","u":"procedures/calculate-period.html","x":"to calculate-period :elapsed :swings [\n  about \"Divide the elapsed time by the number of full swings.\"\n  output :elapsed / :swings\n]"},{"a":"Compare the two periods. A difference within the timing uncertainty does not support the starting hypothesis.","k":"Stage","t":"Compare","u":"stages/compare.html","x":"start stage Compare by researcher from state [\n  set information to [set large-period to 2.01 set small-period to 2.00 set unit to \"s\"]\n]\n  about \"Compare the two periods. A difference within the timing uncertainty\n  does not support the starting hypothesis.\"\n  do compare-periods with [\n    large at large-period of information\n    small at small-period of information\n  ] into difference of information\nend stage with state [\n  set information to [\n    set large-period to 2.01\n    set small-period to 2.00\n    set unit to \"s\"\n    set difference to unknown\n  ]\n]"},{"a":"Subtract the period at a small swing from the period at a large swing.","k":"Procedure","t":"compare-periods","u":"procedures/compare-periods.html","x":"to compare-periods :large :small [\n  about \"Subtract the period at a small swing from the period at a large swing.\"\n  output :large - :small\n]"},{"a":"Record that the measurements did not support the starting hypothesis, and state the new one: the period is nearly constant within the observed range.","k":"Stage","t":"Revise","u":"stages/revise.html","x":"start stage Revise\n  about \"Record that the measurements did not support the starting hypothesis,\n  and state the new one: the period is nearly constant within the observed\n  range.\""},{"a":"Record types used in the method.","k":"Reference","t":"Reference","u":"reference.html","x":""},{"a":"","k":"Performer","t":"assistant","u":"index.html#performer-assistant","x":"performer assistant [set kind to \"human\" set role to \"laboratory assistant\"]"},{"a":"","k":"Performer","t":"researcher","u":"index.html#performer-researcher","x":"performer researcher [set kind to \"human\" set role to \"scientist\"]"},{"a":"A smaller swing has a shorter period.","k":"Hypothesis","t":"shorter-swing","u":"index.html#hypothesis-shorter-swing","x":"hypothesis shorter-swing [set text to \"A smaller swing has a shorter period.\"]"},{"a":"Hand timing is comparable across trials.","k":"Assumption","t":"hand-timing","u":"index.html#assumption-hand-timing","x":"assumption hand-timing [set text to \"Hand timing is comparable across trials.\"]"},{"a":"The period stayed nearly constant as the swing got smaller.","k":"Conclusion","t":"regular-period","u":"index.html#conclusion-regular-period","x":"conclusion regular-period [\n  set text to \"The period stayed nearly constant as the swing got smaller.\"\n]"},{"a":"","k":"Record type","t":"Timing","u":"reference.html#record-timing","x":"interface Timing [\n  version \"1\"\n  must [elapsed is a number swing-count is a number set unit to \"s\"]\n]"}];
